    def retrieve(
        self,
        alert_id: str,
        **options: Unpack[RequestOptions],
    ) -> TransactionAlert:
        """One alert

        The alert, the rule as it was at that version, and its transactions (no names or accounts). Needs `cases.read`.

        GET /v1/transaction-alerts/{alert_id} · scope cases.read
        """
        return self._client._call("transactionAlerts.retrieve", (alert_id,), None, options)  # type: ignore[no-any-return]


