    async def create(
        self,
        params: VerificationRequest,
        **options: Unpack[RequestOptions],
    ) -> Verification:
        """Check an ID number

        Asks the government record behind an ID number (through a provider) and answers with what
        it says: `found` (with the person on the record), `not_found`, or `invalid` (not a valid
        number there) — and Compliwa's own match of the names and date of birth you sent against
        the record. Compliwa never decides whether to accept the person; you do.

        POST /v1/verifications · idempotent (retried safely)
        """
        return await self._client._call("verifications.create", (), params, options)  # type: ignore[no-any-return]

