class AsyncWalletScreeningsResource:
    """client.wallet_screenings"""

    chains: AsyncWalletScreeningsChainsResource

    def __init__(self, client: "AsyncCompliwa") -> None:
        self._client = client
        self.chains = AsyncWalletScreeningsChainsResource(client)

    async def create(
        self,
        params: WalletScreeningRequest,
        **options: Unpack[RequestOptions],
    ) -> WalletScreening:
        """Screen a wallet address

        Checks one address before a deposit is credited or a withdrawal is sent, against:
        - the wallet addresses the official sanctions lists publish (OFAC's "Digital Currency Address"
          identifiers on the SDN and non-SDN lists) — each finding names the list entry, its
          programmes, the day it was listed and the exact list version;
        - the connected provider (TRM Labs' Sanctions API when `TRM_API_KEY` is set), whose "sanctioned"
          is recorded with its name — when it cannot answer, the lists still do and the screening says so;
        - your own list of high-risk wallets (dashboard).

        POST /v1/wallet-screenings · scope kyc.run · idempotent (retried safely)
        """
        return await self._client._call("walletScreenings.create", (), params, options)  # type: ignore[no-any-return]

    def list(
        self,
        params: Optional[ListWalletScreeningsParams] = None,
        **options: Unpack[RequestOptions],
    ) -> AsyncPaginator[WalletScreening]:
        """Wallet screenings

        Newest first, with counts. Filter by `outcome` (also `findings` and `listed_later`), `review`,
        `direction`, `chain`, your `reference`, or one `address` (every screening of it). Needs
        `kyc.read`.

        GET /v1/wallet-screenings
        """
        return self._client._call("walletScreenings.list", (), params, options)  # type: ignore[no-any-return]

    async def retrieve(
        self,
        wallet_screening_id: str,
        **options: Unpack[RequestOptions],
    ) -> WalletScreening:
        """One wallet screening

        What it found (each finding with its source), the lists and provider asked, the review, whether
        a later list named the address ("listed later"), and how often the address was screened before.
        Needs `kyc.read`.

        GET /v1/wallet-screenings/{wallet_screening_id} · scope kyc.read
        """
        return await self._client._call("walletScreenings.retrieve", (wallet_screening_id,), None, options)  # type: ignore[no-any-return]


class AsyncWebhookEndpointsResource:
    """client.webhook_endpoints"""

    def __init__(self, client: "AsyncCompliwa") -> None:
        self._client = client

    async def create(
        self,
        params: KeyCreateWebhookEndpointRequest,
        **options: Unpack[RequestOptions],
    ) -> WebhookEndpointWithSecret:
        """Subscribe to events

        Adds an endpoint in your key's environment: where Compliwa POSTs the events you choose (or
        `["*"]` for every type). The answer holds the signing secret, the only time it is shown: keep
        it to check each webhook's `Compliwa-Signature`. The address must be https and public (outside
        production, http and your own machine are allowed) and is checked again at every send. Up to
        10 per environment. The dashboard shows which key added it. Needs `webhooks.manage`.

        POST /v1/webhook-endpoints · scope webhooks.manage
        """
        return await self._client._call("webhookEndpoints.create", (), params, options)  # type: ignore[no-any-return]

    async def delete(
        self,
        endpoint_id: str,
        **options: Unpack[RequestOptions],
    ) -> WebhookEndpointDeleted:
        """Unsubscribe

        Removes the endpoint: nothing more is sent to it, and deliveries still waiting are canceled.
        Its delivery log stays in the dashboard for 30 days. Needs `webhooks.manage`.

        DELETE /v1/webhook-endpoints/{endpoint_id} · scope webhooks.manage
        """
        return await self._client._call("webhookEndpoints.del", (endpoint_id,), None, options)  # type: ignore[no-any-return]

    async def list(
        self,
        **options: Unpack[RequestOptions],
    ) -> WebhookEndpointList:
        """Your webhook endpoints

        The endpoints of your key's environment, with how their deliveries went in the last 24 hours
        and, for each, the API key that added it (or null when a person did). Needs `webhooks.manage`.

        GET /v1/webhook-endpoints · scope webhooks.manage
        """
        return await self._client._call("webhookEndpoints.list", (), None, options)  # type: ignore[no-any-return]

    async def retrieve(
        self,
        endpoint_id: str,
        **options: Unpack[RequestOptions],
    ) -> WebhookEndpoint:
        """One webhook endpoint

        One endpoint of your key's environment and its health. Needs `webhooks.manage`.

        GET /v1/webhook-endpoints/{endpoint_id} · scope webhooks.manage
        """
        return await self._client._call("webhookEndpoints.retrieve", (endpoint_id,), None, options)  # type: ignore[no-any-return]

    async def update(
        self,
        endpoint_id: str,
        params: UpdateWebhookEndpointRequest,
        **options: Unpack[RequestOptions],
    ) -> WebhookEndpoint:
        """Change a webhook endpoint

        Its address, description, events, or switch it off and on (on again: failures count from now).
        Needs `webhooks.manage`.

        PATCH /v1/webhook-endpoints/{endpoint_id} · scope webhooks.manage
        """
        return await self._client._call("webhookEndpoints.update", (endpoint_id,), params, options)  # type: ignore[no-any-return]


